mapper.sql:
WHERE commissions.status >= 1

    AND (
    commissions.description LIKE CONCAT('%', #{filter.searchText}, '%')
    OR commissions.code LIKE CONCAT('%', #{filter.searchText}, '%')
    )


    AND commissions.start >= #{filter.dateFrom}


    AND commissions.end <= #{filter.dateTo}


    AND commissions.status = #{filter.status}

mapper.select:
SELECT



ORDER BY


        ${filter.orderBy}


        commissions.code DESC



    LIMIT #{filter.page}, #{filter.rowsPerPage}

mapper.insert:
INSERT INTO commission_employees (
    commission_id,
    employee_id
) VALUES (
    #{employee.commissionId},
    #{employee.employeeId}
)
